        object runAttached=Field(storage,"RunPiles").GetValue(null)!;
        var targets=new[]{TaskPileMembershipProof.Getter(typeof(CardModel),"Pile"),TaskPileMembershipProof.Getter(typeof(Player),"Piles"),
            TaskPileMembershipProof.Getter(typeof(PlayerCombatState),"AllPiles"),TaskPileMembershipProof.Getter(typeof(CardPile),"Cards"),
            typeof(CardModel).GetMethods(flags).Single(m=>m.Name.Contains("<get_Pile>",StringComparison.Ordinal)),
            TaskPileMembershipProof.Method(storage,"GetRunPiles"),
