using System;
using System.Collections.Generic;
using System.Linq;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using STS2RitsuLib.Utils;

namespace STS2RitsuLib.CardPiles;

/// <summary>
///     <para xml:lang="en">Stores lazily created mod card piles by their owning combat or player state.</para>
///     <para xml:lang="zh-CN">按所属战斗状态或玩家状态存储延迟创建的模组卡牌牌堆。</para>
/// </summary>
/// <remarks>
///     <para xml:lang="en">
///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> piles are keyed by <see cref="T:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState" />
///         and implicitly disposed with the combat (the <c>AllPiles</c> postfix adds them into the vanilla
///         cleanup sweep).
///     </para>
///     <para xml:lang="en">
///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.RunPersistent" /> piles are keyed by <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" /> and
///         persist across combats for the lifetime of the player instance. Their contents are serialized
///         by <see cref="T:STS2RitsuLib.CardPiles.ModCardPilePersistence" />.
///     </para>
///     <para xml:lang="zh-CN">
///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> 牌堆按 <see cref="T:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState" /> 索引，
///         并随战斗状态释放；<c>AllPiles</c> 补丁会将它们纳入原版的清理流程。
///     </para>
///     <para xml:lang="zh-CN">
///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.RunPersistent" /> 牌堆按 <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" /> 索引，并在玩家实例
///         生命周期内跨战斗保留。其内容由 <see cref="T:STS2RitsuLib.CardPiles.ModCardPilePersistence" /> 序列化。
///     </para>
/// </remarks>
internal static class ModCardPileStorage
{
	private static readonly AttachedState<PlayerCombatState, Dictionary<PileType, ModCardPile>> CombatPiles = new AttachedState<PlayerCombatState, Dictionary<PileType, ModCardPile>>((Func<Dictionary<PileType, ModCardPile>>)null);

	private static readonly AttachedState<Player, Dictionary<PileType, ModCardPile>> RunPiles = new AttachedState<Player, Dictionary<PileType, ModCardPile>>((Func<Dictionary<PileType, ModCardPile>>)null);

	/// <summary>
	///     <para xml:lang="en">
	///         Gets or creates the <paramref name="type" /> pile associated with <paramref name="player" />,
	///         or returns <see langword="null" /> when the type is unregistered or its required state is
	///         unavailable.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         获取或创建与 <paramref name="player" /> 关联的 <paramref name="type" /> 牌堆；类型未注册或
	///         所需状态不可用时返回 <see langword="null" />。
	///     </para>
	/// </summary>
	public static ModCardPile? Resolve(PileType type, Player? player)
	{
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		if (player == null)
		{
			return null;
		}
		if (!ModCardPileRegistry.TryGetByPileType(type, out ModCardPileDefinition definition))
		{
			return null;
		}
		return definition.Scope switch
		{
			ModCardPileScope.CombatOnly => ResolveCombatPile(player.PlayerCombatState, definition), 
			ModCardPileScope.RunPersistent => ResolveRunPile(player, definition), 
			_ => null, 
		};
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Returns a snapshot of existing mod piles owned by <paramref name="state" /> without creating
	///         missing piles.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         返回 <paramref name="state" /> 当前已有模组牌堆的快照，不创建缺失的牌堆。
	///     </para>
	/// </summary>
	public static IReadOnlyCollection<ModCardPile> GetCombatPiles(PlayerCombatState state)
	{
		ArgumentNullException.ThrowIfNull(state, "state");
		Dictionary<PileType, ModCardPile> dictionary = default(Dictionary<PileType, ModCardPile>);
		if (!CombatPiles.TryGetValue(state, ref dictionary) || dictionary.Count == 0)
		{
			return (IReadOnlyCollection<ModCardPile>)(object)Array.Empty<ModCardPile>();
		}
		lock (dictionary)
		{
			return new global::<>z__ReadOnlyArray<ModCardPile>(dictionary.Values.ToArray());
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Returns every registered combat-only pile for <paramref name="state" />, creating missing
	///         instances.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         返回 <paramref name="state" /> 的所有已注册战斗专用牌堆，并创建缺失的实例。
	///     </para>
	/// </summary>
	public static IReadOnlyCollection<ModCardPile> GetOrCreateCombatPiles(PlayerCombatState state)
	{
		//IL_0064: Unknown result type (might be due to invalid IL or missing references)
		//IL_0073: Unknown result type (might be due to invalid IL or missing references)
		ArgumentNullException.ThrowIfNull(state, "state");
		ModCardPileDefinition[] combatDefinitionsSnapshot = ModCardPileRegistry.GetCombatDefinitionsSnapshot();
		if (combatDefinitionsSnapshot.Length == 0)
		{
			return (IReadOnlyCollection<ModCardPile>)(object)Array.Empty<ModCardPile>();
		}
		Dictionary<PileType, ModCardPile> orAdd = CombatPiles.GetOrAdd(state, (Func<PlayerCombatState, Dictionary<PileType, ModCardPile>>)((PlayerCombatState _) => new Dictionary<PileType, ModCardPile>()));
		lock (orAdd)
		{
			ModCardPileDefinition[] array = combatDefinitionsSnapshot;
			foreach (ModCardPileDefinition modCardPileDefinition in array)
			{
				if (!orAdd.ContainsKey(modCardPileDefinition.PileType))
				{
					orAdd[modCardPileDefinition.PileType] = new ModCardPile(modCardPileDefinition);
				}
			}
			return new global::<>z__ReadOnlyArray<ModCardPile>(orAdd.Values.ToArray());
		}
	}

